  ('43fdc4de-27fe-4a40-aadf-f5ad416b471b', 'Beth Israel Deaconess Medical Center Transplant Hepatology Fellowship', 'Beth Israel Deaconess Medical Center (Harvard Medical School)', ARRAY['Hepatology']::text[], 'Boston', 'MA', 'fellowship', true, true, 'https://www.bidmc.org/medical-education/medical-education-by-department/medicine/medicine-fellowships/gastroenterology-fellowship/transplant-hepatology-fellowship', NULL, 'ACGME-accredited 1-year fellowship. 2 positions. Accepts international applicants. Program Director: Michelle Lai. Meets ABIM requirements for transplant hepatology board eligibility.', true, '2026-08-16T01:39:58.161422', NULL, NULL, NULL, NULL, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
  ('883c6585-95de-42c7-b7d0-62ef4d18180c', 'University of California San Francisco (UCSF) Transplant Hepatology Fellowship', 'University of California, San Francisco', ARRAY['Hepatology']::text[], 'San Francisco', 'CA', 'fellowship', true, true, 'https://gastroenterology.ucsf.edu/transplant-hepatology-fellowship', NULL, 'ACGME-accredited 1-year fellowship. 3 positions. Large liver transplant program (190+ per year, 3000+ since 1988). Living donor program. Program Director: Courtney Sherman, MD. J1 only.', true, '2026-08-16T01:39:58.161457', NULL, NULL, NULL, NULL, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
  ('e2635008-ce02-4611-a738-dfec68ace4c4', 'Cedars Sinai Medical Center Transplant Hepatology Fellowship', 'Cedars Sinai Medical Center', ARRAY['Hepatology']::text[], 'Los Angeles', 'CA', 'fellowship', true, true, 'https://www.cedars-sinai.edu/education/graduate-medical/fellowship.html', NULL, 'ACGME-accredited 1-year fellowship. 120-130 liver transplants/year. 8 full-time transplant hepatologists. $12,000 housing stipend, $2,000 educational fund, $3,600 meal card, $1,000 relocation fund. Program Director: Alexander Kuo, MD.', true, '2026-08-16T01:39:58.161494', NULL, NULL, NULL, NULL, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
  ('a921a221-a096-4c9f-a83e-ac52bfe0a6d5', 'University of Colorado Transplant Hepatology Fellowship', 'University of Colorado School of Medicine / Anschutz Medical Campus', ARRAY['Hepatology']::text[], 'Aurora', 'CO', 'fellowship', true, true, 'https://medschool.cuanschutz.edu/gastroenterology/fellowship/transplant-hepatology-fellowship-program', NULL, 'ACGME-accredited 1-year fellowship. One of the largest and longest-running liver transplant programs in the world (started by Dr. Tom Starzl, first human liver transplant 1963). ~140 transplants/year. J1 and H1B accepted.', true, '2026-08-16T01:39:58.161532', NULL, NULL, NULL, NULL, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
  ('1b1cafea-805c-4f5d-bdaa-4178a56e4f25', 'David Geffen School of Medicine at UCLA Transplant Hepatology Fellowship', 'David Geffen School of Medicine at UCLA', ARRAY['Hepatology']::text[], 'Los Angeles', 'CA', 'fellowship', true, true, 'https://www.uclahealth.org/divisions/gastro/fellowship/advanced-programs/liver-transplantation-and-fellowship/transplant-hepatology-fellowship', NULL, 'ACGME-accredited 1-year fellowship. 1 position. Large transplant center. Program Director: Steven-Huy Han, MD. Requires separate UCLA application in addition to AASLD App.', true, '2026-08-16T01:39:58.161566', NULL, NULL, NULL, NULL, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
  ('64c484a7-d3e3-4bc5-b9aa-03f6ed0591fa', 'Duke Health Transplant Hepatology Fellowship', 'Duke University School of Medicine', ARRAY['Hepatology']::text[], 'Durham', 'NC', 'fellowship', true, true, 'https://medicine.duke.edu/divisions/gastroenterology/education-and-training/advanced-training/advanced-transplant-hepatology-fellowship', NULL, 'ACGME-accredited 1-year fellowship. 2000+ liver transplants since 1984. Largest program in NC/SC/VA. Offers multi-visceral, split, domino, living donor transplants. Integrated pediatric liver transplant program. J1, H1B, and E3 accepted.', true, '2026-08-16T01:39:58.161603', NULL, NULL, NULL, NULL, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
  ('db449678-3f9d-4e6c-917f-1e59d2ba0b9d', 'Emory University School of Medicine Transplant Hepatology Fellowship', 'Emory University School of Medicine', ARRAY['Hepatology']::text[], 'Atlanta', 'GA', 'fellowship', true, true, 'https://med.emory.edu/departments/medicine/divisions/digestive-diseases/education/transplant-hepatology.html', NULL, 'ACGME-accredited 1-year fellowship. 2 positions. 6 months inpatient liver transplant service, 6 months outpatient. Research expectation. Program Director: Preeti Reshamwala, MD.', true, '2026-08-16T01:39:58.161636', NULL, NULL, NULL, NULL, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
